define({"topics":[{"title":"Checking and adjusting the patient intercom functionality","shortdesc":"<p class=\"shortdesc\">GOC Audio Assembly (GOCAA) controls are adjusted at factory for best sound quality. This document describes how to check and confirm volume and quality of sound heard from speaker in the magnet bore and from speaker at the Scan Control and Intercom Module (SCIM). Directions for sound adjustments are also provided if needed. <\/p>","href":"t_CheckingThePatientIntercomFunctionality.html","attributes":{"data-id":"id_2011596"},"menu":{"hasChildren":true},"tocID":"id_2011596-d46e97259","next":"id_2011596-d46e97259"},{"title":"Examining the Global Operator Console (GOC) battery replacement","shortdesc":"<p class=\"shortdesc\">Examine the battery replacement sticker on the Global Operator Console (GOC).<\/p>","href":"t_ExaminingTheGOCBatteryReplacement.html","attributes":{"data-id":"id_2004573"},"menu":{"hasChildren":false},"tocID":"id_2004573-d46e97780","topics":[]}]});